describe("scanComponents — data-state blank reporting (#3191)", () => {
  /** A scannable whose LOADED build echoes its id and that carries one state probe echoing `stateEntry`. */
  const withState = (id: string, category: RuntimeStateCategory, stateEntry: string): ScannableComponent => ({
    id, sig: id, files: { entry: id }, entry: "entry",
    states: [{ category, files: { entry: stateEntry }, entry: "entry" }],
  });

  it("reports the render-confirmed blank state of a component that renders fine loaded", async () => {
    const items = [withState("chart", "empty-empty-state", "emptyblank")];
    const bundle = vi.fn(async (files: Record<string, string>) => files.entry);
    // loaded ("chart") renders content; the empty-state build ("emptyblank") renders blank.
    const run: RunFn = async (js) => (js === "emptyblank" ? { ok: true, empty: true } : { ok: true, empty: false });
    const results = new Map<string, RuntimeStateCategory[]>();
    await scanComponents(items, bundle, 2, (id, _status, blanks) => results.set(id, blanks), () => false, run);
    expect(results.get("chart")).toEqual(["empty-empty-state"]);
  });

  it("reports NO blank when the component's empty state renders content (a real EmptyState message)", async () => {
    const items = [withState("good", "empty-empty-state", "emptyfull")];
    const bundle = vi.fn(async (files: Record<string, string>) => files.entry);
    const run: RunFn = async () => ({ ok: true, empty: false }); // every state renders content
    const results = new Map<string, RuntimeStateCategory[]>();
    await scanComponents(items, bundle, 2, (id, _s, b) => results.set(id, b), () => false, run);
    expect(results.get("good")).toEqual([]);
  });

  it("does NOT probe states when the LOADED render is itself blank (that's the #2926 signal, not a state fault)", async () => {
    const items = [withState("blankLoaded", "empty-empty-state", "emptyblank")];
    const bundle = vi.fn(async (files: Record<string, string>) => files.entry);
    const run: RunFn = async () => ({ ok: true, empty: true }); // loaded blank → status "empty"
    const results = new Map<string, RuntimeStateCategory[]>();
    const statuses = new Map<string, string>();
    await scanComponents(items, bundle, 2, (id, status, b) => { results.set(id, b); statuses.set(id, status.state); }, () => false, run);
    expect(statuses.get("blankLoaded")).toBe("empty");
    expect(results.get("blankLoaded")).toEqual([]);
    expect(bundle).toHaveBeenCalledTimes(1); // only the loaded build ran — the state build was skipped
  });

  it("reports [] for a stateless component (no states probed) — e.g. a Button", async () => {
    const items = [sc("button")]; // no `states`
    const bundle = vi.fn(async () => "js");
    const run: RunFn = async () => ({ ok: true, empty: false });
    const results = new Map<string, RuntimeStateCategory[]>();
    await scanComponents(items, bundle, 2, (id, _s, b) => results.set(id, b), () => false, run);
    expect(results.get("button")).toEqual([]);
  });
});

describe("durableLogSync — mirror render results to the durable log (#3540/#3549)", () => {
  it("records a runtime throw's message with a `render:` kind prefix", () => {
    expect(durableLogSync({ state: "ok" }, { state: "error", kind: "runtime", message: "reading map of undefined" }))
      .toBe("render: reading map of undefined");
    // ...even with no prior status (first-visit error).
    expect(durableLogSync(undefined, { state: "error", kind: "runtime", message: "boom" })).toBe("render: boom");
  });

  it("records a BUILD failure too, with a `build:` prefix (#3549 — not always statically detectable)", () => {
    // WorkspaceShellPage built clean by doctor's static analyzer yet esbuild rejected its TS (extensionless
    // src → jsx loader). The REAL build's failure must reach the log so `bsc ui doctor` surfaces it.
    expect(durableLogSync(undefined, { state: "error", kind: "build", message: "Build failed with 1 error" }))
      .toBe("build: Build failed with 1 error");
  });

  it("clears (empty) when a prior error is now ok or empty", () => {
    expect(durableLogSync({ state: "error", kind: "runtime", message: "x" }, { state: "ok" })).toBe("");
    expect(durableLogSync({ state: "error", kind: "build", message: "x" }, { state: "empty", message: "" })).toBe("");
  });

  it("does NOTHING for a healthy or (still) empty component — no first-visit log spam", () => {
    expect(durableLogSync(undefined, { state: "ok" })).toBeNull(); // first-visit ok
    expect(durableLogSync({ state: "ok" }, { state: "ok" })).toBeNull();
    // empty (rendered nothing but did not throw) with no prior error is a no-op too.
    expect(durableLogSync(undefined, { state: "empty", message: "" })).toBeNull();
  });
});

// #4092 — the scan's dependency invalidation never matched, so a fixed dependency left every consumer
// holding a cached failure forever. The 16 components vendoring `ui-charts` kept a 2026-07-28 build
// error that was nine minutes OLDER than the fix for it, and no re-scan could ever clear them.
//
// The old filter compared `build.files` keys against sibling RECORD `src` values. Measured on a real
// `fleetpage` build those never coincide — record src is `src/shared/ui/charts/Charts.tsx`, the build
// key is `shared/ui/charts.tsx` — so nothing ever folded into a signature.
describe("the signature covers the vendored closure, not a path guess (#4092)", () => {
  // The REAL shape: a `provides` component. Its module is keyed from the SPECIFIER
  // (`shared/ui/dep.tsx`) while its record `src` is `src/shared/ui/dep/Dep.tsx` — so the old
  // `sibSrcs.has(key)` filter could never match it, and no edit to it ever re-queued a consumer.
  const dep: ComponentRecord = {
    ...base,
    id: "dep", name: "Dep",
    src: "src/shared/ui/dep/Dep.tsx",
    provides: "@/shared/ui/dep",
    srcText: "export function Dep() { return <i />; }",
  };
  const consumer: ComponentRecord = {
    ...base,
    id: "consumer", name: "Consumer",
    src: "consumer.tsx",
    srcText: 'import { Dep } from "@/shared/ui/dep";\nexport function Consumer() { return <Dep />; }',
  };
  const artifact: KitArtifact = { components: [], runtime: {} };

  it("re-queues a consumer when its DEPENDENCY changes", () => {
    const before = scannableComponents([consumer, dep], artifact).find((s) => s.id === "consumer");
    expect(before, "the consumer must be scannable at all").toBeTruthy();
    const edited = { ...dep, srcText: "export function Dep() { return <b />; }" };
    const after = scannableComponents([consumer, edited], artifact).find((s) => s.id === "consumer")!;
    // THE regression: equal signatures mean `pendingScans` skips it and the stale verdict survives.
    expect(after.sig).not.toBe(before!.sig);
    expect(pendingScans([after], new Map([["consumer", before!.sig]]))).toHaveLength(1);
  });

  it("leaves a component that vendors nothing at sig === buildSignature(c)", () => {
    // The pre-#3112 contract: no dependency ⇒ no extra signature material, so an unrelated edit
    // cannot churn the whole kit through a rebuild.
    const lone: ComponentRecord = { ...base, id: "lone", src: "lone.tsx", srcText: "export function Lone() { return <i />; }" };
    const s = scannableComponents([lone], artifact).find((x) => x.id === "lone")!;
    expect(s.sig).toBe(buildSignature(lone));
  });

  it("digests the vendored bodies too, rather than carrying them", () => {
    // The other half of the 207 MB: the extended signature appended every vendored dependency's FULL
    // body. It must still CHANGE when a dependency changes (the #3112 contract, pinned above) while
    // staying short — so the fold happens before the hash, not after.
    const dep: ComponentRecord = { ...base, id: "dep", name: "Dep", src: "dep.tsx", srcText: `export function Dep() { return <span>${"y".repeat(120_000)}</span>; }` };
    const consumer: ComponentRecord = { ...base, id: "consumer", name: "Consumer", src: "consumer.tsx", srcText: "import { Dep } from './dep'; export function Consumer() { return <Dep />; }" };
    const s = scannableComponents([consumer, dep], artifact).find((x) => x.id === "consumer")!;
    // Differs from the component's own signature ⇒ the dependency really WAS folded in, so the size
    // assertion below is about digested material rather than an empty vendored list.
    expect(s.sig).not.toBe(buildSignature(consumer));
    expect(s.sig.length).toBeLessThan(64);
  });
});

// The scan's BATCHED store write (#4132).
//
// The regression this guards is a performance one with a functional shape: the scan used to call
// `setComponentBuildStatus` + `setComponentStateHealth` per component, so a 248-component sweep produced
// ~496 store commits and the Studio re-rendered its whole 248-node graph on every one (measured: 125
// `[render] designs update` commits at ~24ms). `applyComponentScanResults` collapses a batch into ONE
// commit — so the assertion that matters is the COMMIT COUNT, not just the resulting state.
import { describe, it, expect, beforeEach } from "vitest";
import { useAppStore } from "@/store";
import type { ComponentScanResult } from "@/features/designs/lib/componentScan";

const results = (n: number): ComponentScanResult[] =>
  Array.from({ length: n }, (_, i) => ({
    id: `c${i}`,
    status: { state: "ok" } as const,
    stateBlanks: [],
  }));

describe("applyComponentScanResults", () => {
  beforeEach(() => {
    useAppStore.setState({ componentBuildStatus: {}, componentStateHealth: {} });
  });

  it("commits ONE store update for a whole batch, not two per component", () => {
    let commits = 0;
    const unsub = useAppStore.subscribe(() => { commits += 1; });
    useAppStore.getState().applyComponentScanResults(results(248));
    unsub();
    expect(commits).toBe(1); // the pre-#4132 path was 496
  });

  it("writes both maps for every entry", () => {
    useAppStore.getState().applyComponentScanResults([
      { id: "a", status: { state: "ok" }, stateBlanks: [] },
      { id: "b", status: { state: "error", kind: "build", message: "boom" }, stateBlanks: ["empty-empty-state"] },
    ]);
    const s = useAppStore.getState();
    expect(s.componentBuildStatus.a).toEqual({ state: "ok" });
    expect(s.componentBuildStatus.b).toEqual({ state: "error", kind: "build", message: "boom" });
    expect(s.componentStateHealth.a).toEqual([]);
    expect(s.componentStateHealth.b).toEqual(["empty-empty-state"]);
  });

  it("upserts — a later batch overwrites an earlier verdict and CLEARS a stale blank", () => {
    const st = useAppStore.getState();
    st.applyComponentScanResults([{ id: "a", status: { state: "error", kind: "runtime", message: "x" }, stateBlanks: ["empty-loading-state"] }]);
    st.applyComponentScanResults([{ id: "a", status: { state: "ok" }, stateBlanks: [] }]);
    expect(useAppStore.getState().componentBuildStatus.a).toEqual({ state: "ok" });
    // `[]` is meaningful: a fixed component must lose its prior blank badge.
    expect(useAppStore.getState().componentStateHealth.a).toEqual([]);
  });

  it("preserves entries a batch does not mention", () => {
    const st = useAppStore.getState();
    st.applyComponentScanResults([{ id: "keep", status: { state: "ok" }, stateBlanks: [] }]);
    st.applyComponentScanResults([{ id: "new", status: { state: "ok" }, stateBlanks: [] }]);
    expect(Object.keys(useAppStore.getState().componentBuildStatus).sort()).toEqual(["keep", "new"]);
  });

  it("an empty batch is a no-op — it must not commit an identity-breaking update", () => {
    const before = useAppStore.getState().componentBuildStatus;
    let commits = 0;
    const unsub = useAppStore.subscribe(() => { commits += 1; });
    useAppStore.getState().applyComponentScanResults([]);
    unsub();
    expect(commits).toBe(0);
    expect(useAppStore.getState().componentBuildStatus).toBe(before); // same reference
  });
});
